def canary_decision(metrics, policy):
    if metrics['samples'] < policy['min_samples']:
        return 'hold'
    quality_drop = max(0, (metrics['baseline_quality'] - metrics['candidate_quality']) / metrics['baseline_quality'] * 100)
    if metrics['candidate_p95_ms'] > policy['max_p95_ms'] or quality_drop > policy['max_quality_drop_percent']:
        return 'rollback'
    return 'promote_one_step'
